-- 行前准备（trip_todos）一次性数据播种
-- 由 trip-data.json > preTrip.packingItems 生成，共 153 条。
-- tripId = nz-2026-autumn
--
-- 幂等且不覆盖：使用 ON CONFLICT DO NOTHING —— 只补缺失的行，
-- 绝不改动已存在的行。因此重复执行是安全的，也不会重置你已勾选的项。
--
-- 用法：Cloudflare Dashboard -> 存储和数据库 -> D1 -> 你的库 -> 控制台，
--       把下面的语句逐段粘贴执行（共 4 段，顺序无所谓）。

ON CONFLICT(trip_id, id) DO NOTHING;

ON CONFLICT(trip_id, id) DO NOTHING;

ON CONFLICT(trip_id, id) DO NOTHING;

ON CONFLICT(trip_id, id) DO NOTHING;
